<script setup>
import { onMounted, ref } from 'vue';
import { api, BASE } from '../api';
import { useRouter } from 'vue-router';
const router = useRouter();
const busy = ref(false), error = ref(''), notice = ref(''), ready = ref(false), tokenConfigured = ref(false);
const form = ref({ db_host: '127.0.0.1', db_port: 3306, db_database: 'db_sync_backend', db_username: 'root', db_password: '', hosted_api_url: 'https://quinos.qaccounting.id', runner_token: '' });
async function load() { const status = await fetch(`${BASE}/api/setup/status`).then(r => r.json()); ready.value = status.ready; tokenConfigured.value = status.token_configured; if (status.database) Object.assign(form.value, { db_host: status.database.host, db_port: status.database.port, db_database: status.database.database, db_username: status.database.username }); if (status.hosted_api_url) form.value.hosted_api_url = status.hosted_api_url; }
async function submit() { busy.value = true; error.value = ''; notice.value = ''; try { await api('/setup', { method: 'POST', body: form.value }); notice.value = 'Settings saved and migrations are up to date.'; form.value.runner_token = ''; await load(); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
onMounted(() => load().catch(e => error.value = e.message));
</script>
<template><main class="flex min-h-screen items-center justify-center p-4"><form class="card w-full max-w-2xl space-y-5 p-6" @submit.prevent="submit"><div><h1 class="text-2xl font-semibold">{{ ready ? 'Local sync settings' : 'First-time setup' }}</h1><p class="mt-1 text-sm text-slate-500">Enter the local MySQL connection and hosted runner connection. The app creates the database if permitted and runs pending migrations without dropping existing data.</p></div><p v-if="error" class="rounded-md bg-red-50 px-3 py-2 text-sm text-red-700">{{ error }}</p><p v-if="notice" class="rounded-md bg-green-50 px-3 py-2 text-sm text-green-700">{{ notice }}</p><fieldset class="space-y-3"><legend class="font-semibold">Local MySQL</legend><div class="grid gap-3 sm:grid-cols-2"><label class="text-sm">Host<input v-model="form.db_host" class="field mt-1" required></label><label class="text-sm">Port<input v-model="form.db_port" class="field mt-1" type="number" required></label><label class="text-sm">Database<input v-model="form.db_database" class="field mt-1" required></label><label class="text-sm">Username<input v-model="form.db_username" class="field mt-1" required></label></div><label class="text-sm">Password <span class="text-slate-400">(enter again when changing database)</span><input v-model="form.db_password" class="field mt-1" type="password" autocomplete="new-password"></label></fieldset><fieldset class="space-y-3"><legend class="font-semibold">Hosted runner</legend><label class="text-sm">Hosted URL<input v-model="form.hosted_api_url" class="field mt-1" type="url" required></label><label class="text-sm">API token <span class="text-slate-400">{{ tokenConfigured ? '(leave blank to keep current token)' : '' }}</span><input v-model="form.runner_token" class="field mt-1" type="password" minlength="32" :required="!tokenConfigured"></label></fieldset><div class="flex gap-3"><button class="btn-primary" :disabled="busy">{{ busy ? 'Saving…' : (ready ? 'Save settings' : 'Create database and finish setup') }}</button><button v-if="ready" type="button" class="btn-ghost" @click="router.push('/local-runner')">Cancel</button></div></form></main></template>
